function outputs = run_teacher_twin_test_frozen(config)
%RUN_TEACHER_TWIN_TEST_FROZEN Generate test states after Python freeze.
%
% run_twin_state_cache enforces the signed-off authorization JSON before it
% opens the isolated test input.  The immutable train-based twin audit is
% verified and referenced but is never regenerated by this entry point.

if nargin < 1 || isempty(config)
    config = config_twin_cpi_rc();
end
outputs = run_twin_state_cache('test', config, false);
fprintf('Frozen teacher-final explicit twin test states are ready.\n');
end
